using System.Text.Json.Nodes;
namespace PCRemoteHost;
internal sealed class SharedFolders:Form
{
    readonly string configPath;readonly ListBox list=new(){Width=520,Height=180};readonly List<JsonObject> folders=[];
    public SharedFolders(string root){configPath=Path.Combine(root,"config.json");Text="PC folders · PC Remote";Width=590;Height=410;StartPosition=FormStartPosition.CenterScreen;var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(20),FlowDirection=FlowDirection.TopDown,WrapContents=false};Controls.Add(panel);panel.Controls.Add(new Label{AutoSize=true,MaximumSize=new Size(520,0),Text="Desktop, Documents and Downloads are available automatically. Add another local folder or a network share that Windows can access."});panel.Controls.Add(list);var add=new Button{Text="Add a folder or network share…",AutoSize=true};var remove=new Button{Text="Remove from PC Remote",AutoSize=true};panel.Controls.Add(add);panel.Controls.Add(remove);panel.Controls.Add(new Label{AutoSize=true,Text="Removing a location keeps all its files. Changes apply when Files refreshes."});try{var config=JsonNode.Parse(File.ReadAllText(configPath));if(config?["fileLocations"] is JsonArray items)foreach(var item in items.OfType<JsonObject>())folders.Add((JsonObject)item.DeepClone());}catch{}RefreshList();add.Click+=(_,_)=>{using var picker=new FolderBrowserDialog{Description="Choose a folder or shared network location",UseDescriptionForTitle=true};if(picker.ShowDialog()!=DialogResult.OK)return;if(folders.Count>=16){MessageBox.Show("Use up to sixteen extra folders.");return;}if(folders.Any(item=>string.Equals(item["directory"]?.GetValue<string>(),picker.SelectedPath,StringComparison.OrdinalIgnoreCase)))return;folders.Add(new JsonObject{{"id","@folder-"+Guid.NewGuid().ToString("N")[..10]},{"label",new DirectoryInfo(picker.SelectedPath).Name},{"directory",picker.SelectedPath}});Save();RefreshList();};remove.Click+=(_,_)=>{if(list.SelectedIndex<0)return;folders.RemoveAt(list.SelectedIndex);Save();RefreshList();};}
    void RefreshList(){list.Items.Clear();foreach(var item in folders)list.Items.Add((item["label"]?.GetValue<string>()??"Folder")+" · "+item["directory"]?.GetValue<string>());}
    void Save(){try{var config=JsonNode.Parse(File.ReadAllText(configPath)) as JsonObject??throw new IOException();config["fileLocations"]=new JsonArray(folders.Select(item=>(JsonNode)item.DeepClone()).ToArray());File.WriteAllText(configPath+".folders.tmp",config.ToJsonString());File.Move(configPath+".folders.tmp",configPath,true);}catch{MessageBox.Show("Windows could not save these folder settings. Check the host folder permissions.","PC Remote");}}
}
